ger-text" onclick="return confirm('Gate Pass delete karein? Trip Loaded me wapas aa jayega.')">Delete</button></form><?php endif; ?><a href="PLANNING.php?tab=trips&view=<?=$g['trip_id']?>">Open Trip</a></div></div></td></tr><?php endforeach; ?><?php if(!$gatepasses): ?><tr><td colspan="10" class="note">No Gate Pass created yet.</td></tr><?php endif; ?></table></div></div>
